    border-left: 0;
    border-right: 0;
  }
}
@media only screen and (min-width: 576px) and (max-width: 767px) {
  .tabs-two .nav .nav-item a.active {
    border: 1px solid var(--gray-4);
    border-bottom: 0;
    border-top: 0;
  }
}
.tabs-two .nav .nav-item a.active::before {
  position: absolute;
  content: "";
